    credential: cert(serviceAccount)
  });
}

const db = getFirestore();

interface TestCase {
  flowId: string;
  name: string;
  input: any;
  expectedOutputFields: string[];
}

// Test cases for Phase 1 flows
const PHASE1_TEST_CASES: TestCase[] = [
  {
    flowId: 'generate-text',
